import sys

def main():
    input = sys.stdin.readline

    N, K = map(int, input().split())
    R, S, P = map(int, input().split())
    T = input().strip()

    # Score obtained when winning against each machine hand
    score = {'r': P, 's': R, 'p': S}

    ans = 0
    used_win = [False] * N  # whether we chose the winning hand at round i

    for i in range(N):
        if i < K:
            ans += score[T[i]]
            used_win[i] = True
        else:
            # If taking the winning hand now would repeat the hand used at i-K,
            # and we actually used that winning hand then, we must avoid it.
            if T[i] == T[i - K] and used_win[i - K]:
                used_win[i] = False
            else:
                ans += score[T[i]]
                used_win[i] = True

    print(ans)

if __name__ == "__main__":
    main()
